#!/usr/bin/env bash
set -Eeuo pipefail
umask 077
runtime=/usr/local/lib/ozpanel/sdk/ozsdk.py
[ -f "$runtime" ] || { echo "Install the matching SDK: python3 ozsdk.py runtime-install --confirm" >&2; exit 1; }
work="$(mktemp -d)"
trap 'rm -rf -- "$work"' EXIT
base64 -d > "$work/release.ozaddon" <<'OZ_SIGNED_PACKAGE'

OZ_SIGNED_PACKAGE
root="${OZON_ROOT_DIR:-/etc/ozon}"
python3 "$runtime" --root "$root" verify "$work/release.ozaddon"
if [[ "${OZ_GUI_FORM:-0}" != "1" ]] && [[ "${1:-}" != "--yes" ]]; then
  read -r -p "Install/upgrade SDK addon 9002 5.0.0? [y/N]: " answer
  [[ "$answer" =~ ^[Yy]$ ]] || exit 0
fi
python3 "$runtime" --root "$root" install "$work/release.ozaddon" --confirm --legacy
python3 "$runtime" --root "$root" run 9002
